package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testDivide_NormalValues() {
        Complex c = new Complex(10.0, 20.0);
        Complex result = c.divide(2.0);
        assertEquals(5.0, result.getReal(), DELTA);
        assertEquals(10.0, result.getImaginary(), DELTA);
    }

    @Test
    public void testDivide_NegativeDivisor() {
        Complex c = new Complex(10.0, -20.0);
        Complex result = c.divide(-2.0);
        assertEquals(-5.0, result.getReal(), DELTA);
        assertEquals(10.0, result.getImaginary(), DELTA);
    }

    @Test
    public void testDivide_NaN_InputComplex() {
        Complex c = Complex.NaN;
        Complex result = c.divide(5.0);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_NaN_InputDivisor() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(Double.NaN);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(0.0);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor_WithZeroComplex() {
        Complex c = Complex.ZERO;
        Complex result = c.divide(0.0);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor_FiniteComplex() {
        Complex c = new Complex(5.0, 5.0);
        Complex result = c.divide(Double.POSITIVE_INFINITY);
        assertEquals(0.0, result.getReal(), DELTA);
        assertEquals(0.0, result.getImaginary(), DELTA);
        assertFalse(result.isInfinite());
        assertFalse(result.isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor_InfiniteComplex() {
        Complex c = Complex.INFINITY;
        Complex result = c.divide(Double.POSITIVE_INFINITY);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor_NaNComplex() {
        Complex c = Complex.NaN;
        Complex result = c.divide(Double.POSITIVE_INFINITY);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_NegativeInfiniteDivisor_FiniteComplex() {
        Complex c = new Complex(10.0, -10.0);
        Complex result = c.divide(Double.NEGATIVE_INFINITY);
        assertEquals(0.0, result.getReal(), DELTA);
        assertEquals(0.0, result.getImaginary(), DELTA);
    }
}
